var __viaSiteMarkNodesWithoutViaSite=(() => {
    const getPointToObstacleDistance = (point, obstacle) => {
        if (obstacle.shape === "circle") {
            return Math.max(0, Math.hypot(point.x - obstacle.center.x, point.y - obstacle.center.y) -
                obstacle.width / 2);
        }
        const rotationRadians = (-1 * (obstacle.ccwRotationDegrees ?? 0) * Math.PI) / 180;
        const offsetX = point.x - obstacle.center.x;
        const offsetY = point.y - obstacle.center.y;
        const localX = offsetX * Math.cos(rotationRadians) - offsetY * Math.sin(rotationRadians);
        const localY = offsetX * Math.sin(rotationRadians) + offsetY * Math.cos(rotationRadians);
        const outsideX = Math.max(Math.abs(localX) - obstacle.width / 2, 0);
        const outsideY = Math.max(Math.abs(localY) - obstacle.height / 2, 0);
        return Math.hypot(outsideX, outsideY);
    };
    const getObstacleZLayers = (obstacle, layerCount) => {
        const existingZLayers = obstacle.__zLayers ?? obstacle.zLayers;
        if (existingZLayers)
            return existingZLayers;
        return obstacle.layers.map((layer) => mo(layer, layerCount));
    };
    const getObstacleBounds = (obstacle) => {
        const rotationRadians = ((obstacle.ccwRotationDegrees ?? 0) * Math.PI) / 180;
        const cos = Math.abs(Math.cos(rotationRadians));
        const sin = Math.abs(Math.sin(rotationRadians));
        const halfWidth = (obstacle.width / 2) * cos + (obstacle.height / 2) * sin;
        const halfHeight = (obstacle.width / 2) * sin + (obstacle.height / 2) * cos;
        return {
            minX: obstacle.center.x - halfWidth,
            maxX: obstacle.center.x + halfWidth,
            minY: obstacle.center.y - halfHeight,
            maxY: obstacle.center.y + halfHeight,
        };
    };
    const MIN_SEARCH_CELL_SIZE = 0.005;
    const isRoutedNetObstacle = (obstacle, connMap, routedNetIds) => [obstacle.obstacleId, ...obstacle.connectedTo].some((id) => {
        if (!id)
            return false;
        const netId = connMap.getNetConnectedToId(id);
        return netId !== undefined && routedNetIds.has(netId);
    });
    const hasViaSiteInCell = (cell, obstacles, keepOut) => {
        const corners = [
            { x: cell.minX, y: cell.minY },
            { x: cell.maxX, y: cell.minY },
            { x: cell.minX, y: cell.maxY },
            { x: cell.maxX, y: cell.maxY },
        ];
        const center = {
            x: (cell.minX + cell.maxX) / 2,
            y: (cell.minY + cell.maxY) / 2,
        };
        for (const point of [center, ...corners]) {
            if (obstacles.every(({ obstacle }) => getPointToObstacleDistance(point, obstacle) >= keepOut))
                return true;
        }
        if (obstacles.some(({ obstacle }) => corners.every((corner) => getPointToObstacleDistance(corner, obstacle) < keepOut)))
            return false;
        const width = cell.maxX - cell.minX;
        const height = cell.maxY - cell.minY;
        if (Math.max(width, height) <= MIN_SEARCH_CELL_SIZE)
            return false;
        const halves = width >= height
            ? [
                { ...cell, maxX: center.x },
                { ...cell, minX: center.x },
            ]
            : [
                { ...cell, maxY: center.y },
                { ...cell, minY: center.y },
            ];
        return halves.some((half) => hasViaSiteInCell(half, obstacles.filter(({ bounds }) => bounds.minX - keepOut < half.maxX &&
            bounds.maxX + keepOut > half.minX &&
            bounds.minY - keepOut < half.maxY &&
            bounds.maxY + keepOut > half.minY), keepOut));
    };
    const markNodesWithoutViaSite = ({ nodes, srj, connMap, viaDiameter, viaToPadClearance, }) => {
        const routedNetIds = new Set(srj.connections.map((connection) => connMap.getNetConnectedToId(connection.name) ?? connection.name));
        const keepOut = viaDiameter / 2 + viaToPadClearance;
        const hardObstacles = srj.obstacles
            .filter((obstacle) => !isRoutedNetObstacle(obstacle, connMap, routedNetIds))
            .map((obstacle) => ({
            obstacle,
            bounds: getObstacleBounds(obstacle),
            zLayers: getObstacleZLayers(obstacle, srj.layerCount),
        }));
        return nodes.map((node) => {
            if (node._isComponentTopologyNode ||
                node._containsTarget ||
                node._containsObstacle ||
                node.availableZ.length < 2)
                return node;
            const centers = {
                minX: node.center.x - node.width / 2,
                maxX: node.center.x + node.width / 2,
                minY: node.center.y - node.height / 2,
                maxY: node.center.y + node.height / 2,
            };
            if (centers.minX > centers.maxX || centers.minY > centers.maxY)
                return node;
            const nearby = hardObstacles.filter(({ bounds, zLayers }) => zLayers.some((z) => node.availableZ.includes(z)) &&
                bounds.minX - keepOut < centers.maxX &&
                bounds.maxX + keepOut > centers.minX &&
                bounds.minY - keepOut < centers.maxY &&
                bounds.maxY + keepOut > centers.minY);
            if (nearby.length === 0)
                return node;
            const hasViaSite = hasViaSiteInCell(centers, nearby, keepOut);
            return hasViaSite ? node : { ...node, _lacksViaSite: true };
        });
    };
    return markNodesWithoutViaSite;
})();
